do $$declare f jsonb;datos jsonb;begin
 datos=jsonb_build_object('modalidad','ALTO RENDIMIENTO ACADÉMICO','plan_pago_requisito_id',u('pago'),'servicio_social_requisito_id',u('ss'),'fotografias','ENTREGADAS','doc_curp','APROBADO','doc_acta_nacimiento','APROBADO','doc_antecedente','APROBADO','libro',1,'foja',1,'folio_control','FICTICIO-001','fecha_exencion','2026-11-18');
 f=titulacion_guardar_v1(u('a'),u('pr'),null,0,datos,'GUARDAR','Ensayo ficticio');
 perform comprobar('fuentes y snapshot guardados',f->>'plan_pago_requisito_id'=u('pago')::text and f->'requisitos_verificados'->>'criterio_promedio'='>=9.50');
 begin perform titulacion_guardar_v1(u('a'),u('pr'),(f->>'id')::uuid,0,'{}','GUARDAR','Ensayo ficticio');raise exception 'Permitió revisión anterior';exception when serialization_failure then null;end;
 begin perform _titulacion_requisitos_v1(u('a'),u('otropr'),u('pago'),null);raise exception 'Permitió compartir fuente';exception when raise_exception then if sqlerrm not like 'El plan de titulación ya respalda%' then raise;end if;end;
 -- Cambiar una fuente después de consultar debe impedir finalizar con el resultado anterior.
 update recibos set estatus='CANCELADO';
 begin perform titulacion_guardar_v1(u('a'),u('pr'),(f->>'id')::uuid,1,'{}','COMPLETAR','Ensayo ficticio');raise exception 'No rechazó estado cambiado';exception when raise_exception then if sqlerrm='No rechazó estado cambiado' then raise;end if;end;
 update recibos set estatus='ACTIVO';
 f=titulacion_guardar_v1(u('a'),u('pr'),(f->>'id')::uuid,1,'{}','COMPLETAR','Ensayo ficticio');
 perform comprobar('9.50 permite completar con todos los requisitos',f->>'tramite_completado'='true');
 perform comprobar('auditoría conserva la comprobación',exists(select 1 from titulacion_auditoria where accion='COMPLETAR' and despues->'requisitos_verificados'->>'criterio_promedio'='>=9.50'));
end$$;
